-- Who cosponsored which bill in Congress -- 368K links between members and bills.
-- Auto-generated by scripts/gen_evidence_pages.py: 367,742 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("SPONSORSHIP_DATE") as year, count(*) as records
from THE_LIBRARY.GOVERNMENT.BILL_COSPONSORS_FED_GOVINFO_BILL_COSPONSORS
where "SPONSORSHIP_DATE" is not null
group by 1
order by 1
